// Bit-exact parity test for the FULL QSA indexer path (cpp/engine/src/qsa_full.cpp)
// vs vectors generated by the REAL mlx_vlm modules (tools/gen_qsa_full_vectors.py).
// Compares raw bytes (uint32 view), not tolerances, including the None case.
//
// Standalone build (no CMake edits required):
//   MLXROOT=.venv/lib/python3.12/site-packages/mlx
//   xcrun clang++ -std=c++20 -O2 -I"$MLXROOT/include" -Icpp/engine/src \
//       cpp/engine/src/qsa.cpp cpp/engine/src/qsa_full.cpp \
//       cpp/engine/tests/test_qsa_full.cpp \
//       -L"$MLXROOT/lib" -lmlx -Wl,-rpath,"$(pwd)/$MLXROOT/lib" -o /tmp/test_qsa_full
//   /tmp/test_qsa_full cpp/engine/tests/vectors_qsa_full
#include "qsa_full.hpp"

#include <mlx/mlx.h>

#include <cstdint>
#include <cstdio>
#include <fstream>
#include <iterator>
#include <optional>
#include <string>
#include <vector>

namespace mx = mlx::core;
using namespace veystrix::engine;

static bool bit_equal(const mx::array& a, const mx::array& b) {
  if (a.shape() != b.shape()) return false;
  mx::array av = mx::astype(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::astype(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  if (av.size() != bv.size()) return false;
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i)
    if (pa[i] != pb[i]) return false;
  return true;
}

static double get_num(const std::string& s, const std::string& key) {
  auto pos = s.find("\"" + key + "\"");
  if (pos == std::string::npos) return 0.0;
  auto colon = s.find(':', pos);
  size_t i = colon + 1;
  while (i < s.size() && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n')) ++i;
  std::string num;
  for (; i < s.size(); ++i) {
    char c = s[i];
    if (c == ',' || c == '\n' || c == '}' || c == ' ' || c == '\t') break;
    num += c;
  }
  return std::stod(num);
}

static bool get_bool(const std::string& s, const std::string& key) {
  auto pos = s.find("\"" + key + "\"");
  if (pos == std::string::npos) return false;
  auto t = s.find("true", pos);
  auto f = s.find("false", pos);
  if (t == std::string::npos) return false;
  if (f == std::string::npos) return true;
  return t < f;
}

static std::vector<int> get_int_list(const std::string& s,
                                     const std::string& key) {
  std::vector<int> out;
  auto pos = s.find("\"" + key + "\"");
  if (pos == std::string::npos) return out;
  auto lb = s.find('[', pos);
  auto rb = s.find(']', lb);
  if (lb == std::string::npos || rb == std::string::npos) return out;
  for (size_t i = lb + 1; i < rb;) {
    if (s[i] == '-' || (s[i] >= '0' && s[i] <= '9')) {
      size_t j = i;
      if (s[j] == '-') ++j;
      while (j < rb && s[j] >= '0' && s[j] <= '9') ++j;
      out.push_back(std::stoi(s.substr(i, j - i)));
      i = j;
    } else {
      ++i;
    }
  }
  return out;
}

static int run_case(const std::string& root, const std::string& name) {
  std::string dir = root + "/" + name;
  auto load = [&](const char* n) { return mx::load(dir + "/" + n + ".npy"); };
  std::ifstream mf(dir + "/meta.json");
  std::string meta((std::istreambuf_iterator<char>(mf)),
                   std::istreambuf_iterator<char>());

  QSAFullConfig cfg;
  cfg.base.n_heads = static_cast<int>(get_num(meta, "n_heads"));
  cfg.base.kv_heads = static_cast<int>(get_num(meta, "kv_heads"));
  cfg.base.head_dim = static_cast<int>(get_num(meta, "head_dim"));
  cfg.base.compress_ratio = static_cast<int>(get_num(meta, "compress_ratio"));
  cfg.base.token_budget = static_cast<int>(get_num(meta, "token_budget"));
  cfg.base.block_topk = static_cast<int>(get_num(meta, "block_topk"));
  cfg.base.eps = static_cast<float>(get_num(meta, "eps"));
  cfg.rope.dim = static_cast<int>(get_num(meta, "rotary_dim"));
  cfg.rope.base = static_cast<float>(get_num(meta, "rope_base"));
  cfg.rope.mrope_section = get_int_list(meta, "mrope_section");
  cfg.rope.style = "interleaved";
  cfg.rope.attention_scaling =
      static_cast<float>(get_num(meta, "attention_scaling"));
  cfg.rope.max_position_embeddings =
      static_cast<int>(get_num(meta, "max_position_embeddings"));

  mx::array x = load("x");
  mx::array pw = load("proj_weight");
  mx::array qw = load("q_weight");
  mx::array kw = load("k_weight");
  mx::array past_keys = load("past_index_keys");
  mx::array past_pos = load("past_index_positions");
  mx::array positions = load("position_ids");
  mx::array exp_keys = load("expected_index_keys");
  mx::array exp_pos = load("expected_index_positions");

  QSACache cache;
  cache.offset = static_cast<int>(get_num(meta, "past_len"));
  cache.update_indexer(past_keys, past_pos);
  mx::eval(*cache.index_keys, *cache.index_position_ids);

  std::optional<mx::array> out =
      qsa_full_indexer(x, pw, qw, kw, cfg, cache, positions);
  mx::eval(*cache.index_keys, *cache.index_position_ids);
  if (out.has_value()) mx::eval(*out);

  bool expect_none = get_bool(meta, "returned_none");
  if (expect_none != !out.has_value()) {
    std::fprintf(stderr, "[%s] None mismatch (expected %s, got %s)\n",
                 name.c_str(), expect_none ? "None" : "mask",
                 out.has_value() ? "mask" : "None");
    return 1;
  }

  if (!bit_equal(*cache.index_keys, exp_keys)) {
    std::fprintf(stderr, "[%s] updated index_keys differs\n", name.c_str());
    return 1;
  }
  if (!bit_equal(*cache.index_position_ids, exp_pos)) {
    std::fprintf(stderr, "[%s] updated index_position_ids differs\n",
                 name.c_str());
    return 1;
  }
  if (out.has_value()) {
    mx::array exp_mask = load("expected_mask");
    if (!bit_equal(*out, exp_mask)) {
      std::fprintf(stderr, "[%s] qsa_mask differs\n", name.c_str());
      return 1;
    }
    std::printf("  [%s] OK (mask + cache bit-identical, shape (", name.c_str());
    for (size_t i = 0; i < out->shape().size(); ++i)
      std::printf("%s%d", i ? "," : "", static_cast<int>(out->shape()[i]));
    std::printf("))\n");
  } else {
    std::printf("  [%s] OK (None + cache bit-identical)\n", name.c_str());
  }
  return 0;
}

int main(int argc, char** argv) {
  std::string root = argc > 1 ? argv[1] : "cpp/engine/tests/vectors_qsa_full";
  std::ifstream f(root + "/cases.json");
  if (!f) {
    std::fprintf(stderr, "cases.json missing; run gen_qsa_full_vectors.py\n");
    return 2;
  }
  std::string text((std::istreambuf_iterator<char>(f)),
                   std::istreambuf_iterator<char>());
  std::vector<std::string> cases;
  size_t pos = 0;
  while ((pos = text.find("\"dir\"", pos)) != std::string::npos) {
    auto q1 = text.find('"', text.find(':', pos) + 1);
    auto q2 = text.find('"', q1 + 1);
    if (q1 != std::string::npos && q2 != std::string::npos)
      cases.push_back(text.substr(q1 + 1, q2 - q1 - 1));
    pos = q2;
  }
  if (cases.empty()) {
    std::fprintf(stderr, "no cases parsed\n");
    return 2;
  }
  int failed = 0;
  for (const auto& c : cases) failed += run_case(root, c);
  if (failed) {
    std::fprintf(stderr, "%d full-QSA case(s) FAILED\n", failed);
    return 1;
  }
  std::printf("test_qsa_full OK (%zu cases bit-identical to Python)\n",
              cases.size());
  return 0;
}
